import sys
from itertools import combinations

def landau_check(scores):
    n = len(scores)
    if n == 0:
        return True
    s = 0
    for k in range(n):
        s += scores[k]
        if s < k * (k + 1) // 2:
            return False
    return s == n * (n - 1) // 2

def build_tournament(scores):
    n = len(scores)
    adj = [[0] * n for _ in range(n)]
    out_deg = [0] * n

    for i in range(n):
        for j in range(i + 1, n):
            if out_deg[i] < scores[i]:
                adj[i][j] = 1
                out_deg[i] += 1
            else:
                adj[j][i] = 1
                out_deg[j] += 1

    for i in range(n):
        if out_deg[i] != scores[i]:
            return None

    return adj

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    m = int(input_data[0])
    S = list(map(int, input_data[1:1+m]))
    S.sort()

    max_n = 60
    found = False
    result_matrix = None
    result_n = 0

    for n in range(m, max_n + 1):
        if n % 2 == 1:
            total_needed = n * (n - 1) // 2
        else:
            total_needed = n * (n - 1) //2

        if total_needed < sum(S):
            continue

        counts = {}
        for x in S:
            counts[x] = counts.get(x, 0) + 1

        current_scores = []
        for val, count in counts.items():
            current_scores.extend([val] * count)

        needed = n - len(current_scores)
        if needed < 0:
            continue

        for extra in range(needed + 1):
            if extra > 0:
                temp_scores = current_scores[:]
                for _ in range(extra):
                    temp_scores.append(0)
                temp_scores.sort()

                if sum(temp_scores) != n * (n - 1) // 2:
                    continue

                if landau_check(temp_scores):
                    adj = build_tournament(temp_scores)
                    if adj is not None:
                        found = True
                        result_n = n
                        result_matrix = adj
                        break
            else:
                if len(current_scores) != n:
                    continue
                if sum(current_scores) != n * (n - 1) // 2: 
                    continue
                if landau_check(current_scores):
                    adj = build_tournament(current_scores)
                    if adj is not None:
                        found = True 
                        result_n = n
                        result_matrix = adj
                        break

        if found:
            break

    if not found:
        print("=(")
    else:
        print(result_n)
        for row in result_matrix:
            print(''.join(str(x) for x in row))

if __name__ == "__main__":
    solve()
